<?php if($cmsUnavailable):?><p class="notice">Published updates are temporarily unavailable. Please return later.</p>
<?php elseif($story):$privatePreview=false;require __DIR__.'/content-story.php';?><p><a class="text-link" href="<?= e(url('updates')) ?>">← All updates</a></p>
<?php elseif($publicUpdates||$visibleCategories):$filter=isset($_GET['category'])&&is_string($_GET['category'])?$_GET['category']:'';?>
<form class="gallery-filter" method="get" action="<?= e(url('updates')) ?>"><input type="hidden" name="page" value="updates"><label for="category_filter">Filter updates by category</label><select id="category_filter" name="category"><option value="">All categories</option><?php foreach($visibleCategories as $id=>$name):?><option value="<?= (int)$id ?>"<?= $filter===(string)$id?' selected':'' ?>><?= e($name) ?></option><?php endforeach;?></select><button class="button">Filter updates</button></form><div class="content-grid"><?php $found=false;foreach($publicUpdates as $entry):if($filter!==''&&$filter!==(string)$entry['category_id']){continue;}$found=true;?><article class="content-card"><?php if($entry['cover_asset_id']):?><img src="<?= e(c_media_url((int)$entry['cover_asset_id'],480)) ?>" alt="<?= e($entry['alt_text']) ?>" width="480" height="320" loading="lazy"><?php endif;?><p class="eyebrow"><?= e($entry['category']??C_KINDS[$entry['kind']]) ?></p><h2><a href="<?= e(c_public_url($entry)) ?>"><?= e($entry['title']) ?></a></h2><p><?= e($entry['excerpt']) ?></p></article><?php endforeach;if(!$found):?><p>No published updates match this category.</p><?php endif;?></div>
<?php else:?><span class="badge">NO PUBLISHED UPDATES</span><h2>Room for the next chapter.</h2><p>Approved announcements, production diaries and behind-the-scenes updates will appear here. No production milestones or release dates have been announced on this site.</p><?php endif;?>

<?php if(!$story&&($moreUpdates||$publicListPage>1)):?><nav class="pager" aria-label="Updates pages"><?php if($publicListPage>1):?><a href="<?= e(url('updates').'&'.http_build_query(['list_page'=>$publicListPage-1,'category'=>$categoryFilter])) ?>">← Previous updates</a><?php endif;if($moreUpdates):?><a href="<?= e(url('updates').'&'.http_build_query(['list_page'=>$publicListPage+1,'category'=>$categoryFilter])) ?>">Next updates →</a><?php endif;?></nav><?php endif;?>
